def echo(message, **_extra):
    import json, os, datetime, time, math, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0338000" if __import__("os").path.isdir("./environment_mix/0338000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(x):
        return isinstance(x, str)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(invocations, api_key_id, session_id, page_id, tool_name, status, input_obj, output_obj=None, error_message=None, duration_ms=None, sequence_no=0):
        ts = _now()
        inv = {
            "id": _new_id("inv"),
            "api_key_id": api_key_id,
            "session_id": session_id,
            "page_id": page_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj,
            "output": output_obj,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "sequence_no": sequence_no,
            "created_at": ts,
            "updated_at": ts,
        }
        invocations.append(inv)
        return inv

    # Validate input
    if not _is_str(message):
        return _err("VALIDATION_ERROR", "`message` is required and must be a string.")

    api_keys = _load("api_keys.json")
    tool_invocations = _load("tool_invocations.json")

    # Ambient authentication: pick an active key that can serve requests
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        # No invocation row should be created if not authenticated
        return _err("UNAUTHORIZED", "No active API key available.")

    # Enforce rate limit per api key (requests per minute)
    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(seconds=60)

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    chosen = None
    for k in active_keys:
        rpm = k.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            continue
        kid = k.get("id")
        if not isinstance(kid, str) or not kid:
            continue
        recent = 0
        for inv in tool_invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("api_key_id") != kid:
                continue
            ts = _parse_ts(inv.get("created_at"))
            if ts is not None and ts >= one_min_ago:
                recent += 1
        if recent < rpm:
            chosen = k
            break

    if chosen is None:
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Create invocation row (echo implies session_id is null)
    kid = chosen["id"]
    inv = _log(
        tool_invocations,
        api_key_id=kid,
        session_id=None,
        page_id=None,
        tool_name="echo",
        status="running",
        input_obj={"message": message},
        sequence_no=0,
    )

    # Execute
    output = {"message": message}

    inv["status"] = "succeeded"
    inv["output"] = output
    inv["duration_ms"] = int((time.time() - t0) * 1000)
    inv["updated_at"] = _now()

    # Update api key last_used_at/updated_at
    ts_now = _now()
    chosen["last_used_at"] = ts_now
    chosen["updated_at"] = ts_now

    _save("tool_invocations.json", tool_invocations)
    _save("api_keys.json", api_keys)

    return {"message": message}

def get_all_content(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0338000" if __import__("os").path.isdir("./environment_mix/0338000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _allocate_sequence(invocations, session_id):
        max_seq = -1
        for inv in invocations:
            if isinstance(inv, dict) and inv.get("session_id") == session_id:
                sn = inv.get("sequence_no")
                if isinstance(sn, int) and sn > max_seq:
                    max_seq = sn
        return max_seq + 1

    def _log(invocations, api_key_id, session_id, page_id, tool_name, status, input_obj, output_obj=None, error_message=None, duration_ms=None, sequence_no=0):
        ts = _now()
        inv = {
            "id": _new_id("inv"),
            "api_key_id": api_key_id,
            "session_id": session_id,
            "page_id": page_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj,
            "output": output_obj,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "sequence_no": sequence_no,
            "created_at": ts,
            "updated_at": ts,
        }
        invocations.append(inv)
        return inv

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    pages = _load("pages.json")
    tool_invocations = _load("tool_invocations.json")
    page_snapshots = _load("page_snapshots.json")

    # Auth selection: active key with active session and current page
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available.")

    # Rate limit pick
    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(seconds=60)

    chosen_key = None
    chosen_session = None
    chosen_page = None

    for k in active_keys:
        rpm = k.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            continue
        kid = k.get("id")
        if not isinstance(kid, str) or not kid:
            continue

        sess = None
        for s in sessions:
            if isinstance(s, dict) and s.get("api_key_id") == kid and s.get("status") == "active":
                sess = s
                break
        if sess is None:
            continue
        pid = sess.get("current_page_id")
        if not isinstance(pid, str) or not pid:
            continue
        pg = None
        for p in pages:
            if isinstance(p, dict) and p.get("id") == pid and p.get("session_id") == sess.get("id"):
                pg = p
                break
        if pg is None:
            continue

        recent = 0
        for inv in tool_invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("api_key_id") != kid:
                continue
            ts = _parse_ts(inv.get("created_at"))
            if ts is not None and ts >= one_min_ago:
                recent += 1
        if recent < rpm:
            chosen_key, chosen_session, chosen_page = k, sess, pg
            break

    if chosen_key is None:
        any_key_session_page = False
        for k in active_keys:
            kid = k.get("id")
            for s in sessions:
                if isinstance(s, dict) and s.get("api_key_id") == kid and s.get("status") == "active" and isinstance(s.get("current_page_id"), str) and s.get("current_page_id"):
                    any_key_session_page = True
                    break
            if any_key_session_page:
                break
        if any_key_session_page:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return _err("NOT_FOUND", "No active session/page exists to read from.")

    # Readability state: require page not loading/error
    if chosen_page.get("status") in ("loading", "error"):
        return _err("CONFLICT", "Page is not in a readable state.")

    session_id = chosen_session["id"]
    page_id = chosen_page["id"]

    seq = _allocate_sequence(tool_invocations, session_id)
    inv = _log(
        tool_invocations,
        api_key_id=chosen_key["id"],
        session_id=session_id,
        page_id=page_id,
        tool_name="get_all_content",
        status="running",
        input_obj={},
        sequence_no=seq,
    )

    # Produce snapshot from current page info
    final_url = chosen_page.get("final_url") or chosen_page.get("url")
    title = chosen_page.get("title") or ""
    content_html = f"<!doctype html><html><head><title>{title}</title></head><body><p>Snapshot for {final_url}</p></body></html>"

    inv["status"] = "succeeded"
    inv["output"] = {"pageId": page_id, "sessionId": session_id, "contentHtml": content_html}
    inv["duration_ms"] = int((time.time() - t0) * 1000)
    inv["updated_at"] = _now()

    # Create snapshot only for succeeded invocation, unique(tool_invocation_id)
    snap = {
        "id": _new_id("snap"),
        "session_id": session_id,
        "page_id": page_id,
        "tool_invocation_id": inv["id"],
        "snapshot_type": "all_content",
        "min_visible_percentage": None,
        "content_html": content_html,
        "content_text": None,
        "interactive_elements": None,
        "status": "stored",
        "created_at": _now(),
        "updated_at": _now(),
        "expires_at": None,
    }
    page_snapshots.append(snap)

    # Update api key usage stamps
    ts_now = _now()
    chosen_key["last_used_at"] = ts_now
    chosen_key["updated_at"] = ts_now

    _save("page_snapshots.json", page_snapshots)
    _save("tool_invocations.json", tool_invocations)
    _save("api_keys.json", api_keys)

    return {"contentHtml": content_html, "snapshotId": snap["id"], "pageId": page_id, "sessionId": session_id}

def get_visible_content(minVisiblePercentage=None, **_extra):
    import json, os, datetime, time, uuid, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0338000" if __import__("os").path.isdir("./environment_mix/0338000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _finite_number(x):
        if isinstance(x, bool) or x is None:
            return False
        if not isinstance(x, (int, float)):
            return False
        return math.isfinite(float(x))

    def _allocate_sequence(invocations, session_id):
        max_seq = -1
        for inv in invocations:
            if isinstance(inv, dict) and inv.get("session_id") == session_id:
                sn = inv.get("sequence_no")
                if isinstance(sn, int) and sn > max_seq:
                    max_seq = sn
        return max_seq + 1

    def _log(invocations, api_key_id, session_id, page_id, tool_name, status, input_obj, output_obj=None, error_message=None, duration_ms=None, sequence_no=0):
        ts = _now()
        inv = {
            "id": _new_id("inv"),
            "api_key_id": api_key_id,
            "session_id": session_id,
            "page_id": page_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj,
            "output": output_obj,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "sequence_no": sequence_no,
            "created_at": ts,
            "updated_at": ts,
        }
        invocations.append(inv)
        return inv

    # Validate minVisiblePercentage if provided
    if minVisiblePercentage is not None:
        if not _finite_number(minVisiblePercentage):
            return _err("VALIDATION_ERROR", "`minVisiblePercentage` must be a finite number in range 0–100.")
        mvp = float(minVisiblePercentage)
        if mvp < 0 or mvp > 100:
            return _err("VALIDATION_ERROR", "`minVisiblePercentage` must be in range 0–100.")
    else:
        mvp = None

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    pages = _load("pages.json")
    tool_invocations = _load("tool_invocations.json")
    page_snapshots = _load("page_snapshots.json")

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available.")

    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(seconds=60)

    chosen_key = None
    chosen_session = None
    chosen_page = None

    for k in active_keys:
        rpm = k.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            continue
        kid = k.get("id")
        if not isinstance(kid, str) or not kid:
            continue

        sess = None
        for s in sessions:
            if isinstance(s, dict) and s.get("api_key_id") == kid and s.get("status") == "active":
                sess = s
                break
        if sess is None:
            continue
        pid = sess.get("current_page_id")
        if not isinstance(pid, str) or not pid:
            continue
        pg = None
        for p in pages:
            if isinstance(p, dict) and p.get("id") == pid and p.get("session_id") == sess.get("id"):
                pg = p
                break
        if pg is None:
            continue

        recent = 0
        for inv in tool_invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("api_key_id") != kid:
                continue
            ts = _parse_ts(inv.get("created_at"))
            if ts is not None and ts >= one_min_ago:
                recent += 1
        if recent < rpm:
            chosen_key, chosen_session, chosen_page = k, sess, pg
            break

    if chosen_key is None:
        any_key_session_page = False
        for k in active_keys:
            kid = k.get("id")
            for s in sessions:
                if isinstance(s, dict) and s.get("api_key_id") == kid and s.get("status") == "active" and isinstance(s.get("current_page_id"), str) and s.get("current_page_id"):
                    any_key_session_page = True
                    break
            if any_key_session_page:
                break
        if any_key_session_page:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return _err("NOT_FOUND", "No active session/page exists to read from.")

    # Readability state
    if chosen_page.get("status") in ("loading", "error"):
        return _err("CONFLICT", "Page is not in a readable state.")

    session_id = chosen_session["id"]
    page_id = chosen_page["id"]

    seq = _allocate_sequence(tool_invocations, session_id)
    input_obj = {}
    if mvp is not None:
        input_obj["minVisiblePercentage"] = mvp

    inv = _log(
        tool_invocations,
        api_key_id=chosen_key["id"],
        session_id=session_id,
        page_id=page_id,
        tool_name="get_visible_content",
        status="running",
        input_obj=input_obj,
        sequence_no=seq,
    )

    final_url = chosen_page.get("final_url") or chosen_page.get("url")
    content_text = f"Visible content for {final_url}"
    if mvp is not None:
        content_text += f" (minVisiblePercentage={mvp:g})"

    inv["status"] = "succeeded"
    inv["output"] = {"pageId": page_id, "sessionId": session_id, "contentText": content_text}
    inv["duration_ms"] = int((time.time() - t0) * 1000)
    inv["updated_at"] = _now()

    snap = {
        "id": _new_id("snap"),
        "session_id": session_id,
        "page_id": page_id,
        "tool_invocation_id": inv["id"],
        "snapshot_type": "visible_content",
        "min_visible_percentage": mvp,
        "content_html": None,
        "content_text": content_text,
        "interactive_elements": None,
        "status": "stored",
        "created_at": _now(),
        "updated_at": _now(),
        "expires_at": None,
    }
    page_snapshots.append(snap)

    ts_now = _now()
    chosen_key["last_used_at"] = ts_now
    chosen_key["updated_at"] = ts_now

    _save("page_snapshots.json", page_snapshots)
    _save("tool_invocations.json", tool_invocations)
    _save("api_keys.json", api_keys)

    return {"contentText": content_text, "snapshotId": snap["id"], "pageId": page_id, "sessionId": session_id}

def move_mouse(x, y, **_extra):
    import json, os, datetime, time, math, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0338000" if __import__("os").path.isdir("./environment_mix/0338000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_finite_number(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(float(v))

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _allocate_sequence_no(invocations, session_id):
        mx = -1
        for r in invocations:
            if r.get("session_id") == session_id:
                try:
                    sn = int(r.get("sequence_no", -1))
                    if sn > mx: mx = sn
                except Exception:
                    pass
        return mx + 1

    def _rate_limit_check(invocations, api_key_row):
        rpm = api_key_row.get("rate_limit_rpm")
        try:
            rpm = int(rpm)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid api key rate limit configuration.")
        if rpm < 1 or rpm > 6000:
            return _err("VALIDATION_ERROR", "Invalid api key rate limit configuration.")
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in invocations:
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _log(invocations, api_key_id, session_id, page_id, status, input_obj, output_obj=None, error_message=None, duration_ms=None, sequence_no=0):
        now = _now()
        inv = {
            "id": _gen_id("inv"),
            "api_key_id": api_key_id,
            "session_id": session_id,
            "page_id": page_id,
            "tool_name": "move_mouse",
            "status": status,
            "input": input_obj,
            "output": output_obj,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "sequence_no": int(sequence_no),
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv)
        return inv

    input_obj = {"x": x, "y": y}
    if _extra:
        input_obj.update(_extra)

    # Validate
    if _extra:
        # unsupported fields for this tool (no additionalProperties in provided schema)
        # treat as validation error
        pass
    if not _is_finite_number(x) or not _is_finite_number(y):
        val_err = _err("VALIDATION_ERROR", "x and y must be finite numbers.")
    elif _extra:
        val_err = _err("VALIDATION_ERROR", "Unsupported fields supplied.", fields=list(_extra.keys()))
    else:
        val_err = None

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    pages = _load("pages.json")
    invocations = _load("tool_invocations.json")

    # Resolve active key + active session + current page
    chosen_key = None
    chosen_session = None
    chosen_page = None

    active_keys = [k for k in api_keys if k.get("status") == "active"]
    for k in active_keys:
        rl_err = _rate_limit_check(invocations, k)
        if rl_err:
            continue
        for s in sessions:
            if s.get("api_key_id") != k.get("id"):
                continue
            if s.get("status") != "active":
                continue
            pid = s.get("current_page_id")
            if not pid:
                continue
            p = next((pp for pp in pages if pp.get("id") == pid and pp.get("session_id") == s.get("id")), None)
            if not p:
                continue
            chosen_key, chosen_session, chosen_page = k, s, p
            break
        if chosen_key:
            break

    if not chosen_key:
        if active_keys:
            any_not_rl = any(_rate_limit_check(invocations, k) is None for k in active_keys)
            if not any_not_rl:
                k = active_keys[0]
                duration_ms = int((time.time() - t0) * 1000)
                _log(invocations, k.get("id"), None, None, "failed", input_obj, output_obj=None,
                     error_message="Rate limit exceeded.", duration_ms=duration_ms, sequence_no=0)
                _save("tool_invocations.json", invocations)
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            k = active_keys[0]
            duration_ms = int((time.time() - t0) * 1000)
            _log(invocations, k.get("id"), None, None, "failed", input_obj, output_obj=None,
                 error_message="No active session/page.", duration_ms=duration_ms, sequence_no=0)
            _save("tool_invocations.json", invocations)
            return _err("NOT_FOUND", "No active session/page to control.")
        return _err("UNAUTHORIZED", "No active API key available.")

    seq = _allocate_sequence_no(invocations, chosen_session.get("id"))

    if val_err:
        duration_ms = int((time.time() - t0) * 1000)
        _log(invocations, chosen_key.get("id"), chosen_session.get("id"), chosen_page.get("id"),
             "failed", input_obj, output_obj=None, error_message=val_err["error"]["message"],
             duration_ms=duration_ms, sequence_no=seq)
        _save("tool_invocations.json", invocations)
        return val_err

    inv = _log(invocations, chosen_key.get("id"), chosen_session.get("id"), chosen_page.get("id"),
               "queued", {"x": float(x), "y": float(y)}, output_obj=None, error_message=None,
               duration_ms=None, sequence_no=seq)
    inv["status"] = "running"
    inv["updated_at"] = _now()

    # Succeed: record pointer state in output (no separate collection)
