def drag_and_drop(sourceX, sourceY, targetX, targetY, **_extra):
    import json, os, datetime, time, math, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0338000" if __import__("os").path.isdir("./environment_mix/0338000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_finite_number(x):
        if not isinstance(x, (int, float)):
            return False
        return math.isfinite(float(x))

    # Validate inputs
    if not _is_finite_number(sourceX):
        return _err("VALIDATION_ERROR", "sourceX must be a finite number.", field="sourceX")
    if not _is_finite_number(sourceY):
        return _err("VALIDATION_ERROR", "sourceY must be a finite number.", field="sourceY")
    if not _is_finite_number(targetX):
        return _err("VALIDATION_ERROR", "targetX must be a finite number.", field="targetX")
    if not _is_finite_number(targetY):
        return _err("VALIDATION_ERROR", "targetY must be a finite number.", field="targetY")

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    pages = _load("pages.json")
    invocations = _load("tool_invocations.json")

    # Authenticate (ambient): must find an active api key AND at least one controllable active session w/ current page
    active_key = None
    active_session = None
    current_page = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        # Find an active session for this key with a current_page_id pointing to an existing page
        for s in sessions:
            if s.get("api_key_id") != k.get("id"):
                continue
            if s.get("status") != "active":
                continue
            pid = s.get("current_page_id")
            if not pid:
                continue
            p = next((pp for pp in pages if pp.get("id") == pid and pp.get("session_id") == s.get("id")), None)
            if not p:
                continue
            active_key = k
            active_session = s
            current_page = p
            break
        if active_key:
            break

    # If there exists no active key at all -> UNAUTHORIZED; otherwise, if keys exist but no active session/page -> NOT_FOUND
    if not active_key:
        # log failed attempt if any key exists? Need api_key_id; without one, do not write invocation row (fk constraint).
        return _err("UNAUTHORIZED", "No active API key is available to authenticate this request.")

    # Rate limit per api key (requests per rolling minute) using tool_invocations.created_at
    rpm = active_key.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in invocations:
        if r.get("api_key_id") == active_key.get("id") and isinstance(r.get("created_at"), str) and r.get("created_at") >= cutoff:
            recent += 1
    if recent >= rpm:
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_rpm=rpm)

    if not active_session or not current_page:
        # record invocation attempt? Constraint: tool_name != echo implies session_id is not null.
        # No valid session/page => cannot create invocation row without violating rule of requiring session for tool.
        # Therefore return NOT_FOUND without mutation.
        return _err("NOT_FOUND", "No active session with a current page is available to control.")

    # Allocate per-session sequence_no atomically-ish by reloading and taking max
    invocations = _load("tool_invocations.json")
    seq = 0
    for r in invocations:
        if r.get("session_id") == active_session.get("id"):
            sn = r.get("sequence_no")
            if isinstance(sn, int) and sn >= seq:
                seq = sn + 1

    inv_id = "inv_" + uuid.uuid4().hex
    inv_row = {
        "id": inv_id,
        "api_key_id": active_key.get("id"),
        "session_id": active_session.get("id"),
        "page_id": current_page.get("id"),
        "tool_name": "drag_and_drop",
        "status": "running",
        "input": {"sourceX": float(sourceX), "sourceY": float(sourceY), "targetX": float(targetX), "targetY": float(targetY)},
        "output": None,
        "error_message": None,
        "duration_ms": None,
        "sequence_no": seq,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv_row)
    _save("tool_invocations.json", invocations)

    # "Perform" gesture: offline simulation; mark succeeded and store a minimal output record
    out = {
        "gesture": "drag_and_drop",
        "source": {"x": float(sourceX), "y": float(sourceY)},
        "target": {"x": float(targetX), "y": float(targetY)},
        "pageId": current_page.get("id"),
        "sessionId": active_session.get("id"),
        "recorded": True,
    }

    duration_ms = int(round((time.time() - t0) * 1000))
    invocations = _load("tool_invocations.json")
    for r in invocations:
        if r.get("id") == inv_id:
            r["status"] = "succeeded"
            r["output"] = out
            r["duration_ms"] = duration_ms if duration_ms >= 0 else 0
            r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("tool_invocations.json", invocations)

    # Update api key last_used_at on successful authenticated request
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == active_key.get("id"):
            k["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            k["updated_at"] = k.get("updated_at") or k["last_used_at"]
            break
    _save("api_keys.json", api_keys)

    return {"invocation": out, "toolInvocationId": inv_id, "sequenceNo": seq, "durationMs": duration_ms}

