        active_count = 0
        for s in sessions:
            if isinstance(s, dict) and s.get("api_key_id") == k.get("id") and s.get("status") == "active":
                active_count += 1
        if active_count < maxc:
            chosen = k
            break

    if chosen is None:
        # At least one active key exists, but all are at max concurrent sessions
        return _err("CONFLICT", "API key has reached max_concurrent_sessions for all available active keys.")

    # Rate limit enforcement uses tool_invocations as request log (observable dynamics)
    rpm = chosen.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
        rpm = 60
    cutoff = (now_dt - datetime.timedelta(seconds=60)).isoformat() + "Z"
    recent = 0
    for r in tool_invocations:
        if isinstance(r, dict) and r.get("api_key_id") == chosen.get("id") and isinstance(r.get("created_at"), str) and r.get("created_at") >= cutoff:
            recent += 1
    if recent >= rpm:
        # Must still log the call
        inv_id = "pwk_call_" + secrets.token_hex(12)
        tool_invocations.append({
            "id": inv_id,
            "api_key_id": chosen.get("id"),
            "session_id": None,
            "page_id": None,
            "tool_name": "echo",
            "status": "failed",
            "input": {"tool": "create_session", "userAgent": userAgent, "viewportWidth": viewportWidth, "viewportHeight": viewportHeight},
            "output": None,
            "error_message": "Rate limit exceeded.",
            "duration_ms": int((time.time() - t0) * 1000),
            "sequence_no": 0,
            "created_at": now,
            "updated_at": now
        })
        _save("tool_invocations.json", tool_invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_rpm=rpm)

    # Create session
    sess_id = "pwk_sess_" + secrets.token_hex(14)
    # Ensure uniqueness
    existing_ids = {s.get("id") for s in sessions if isinstance(s, dict)}
    while sess_id in existing_ids:
        sess_id = "pwk_sess_" + secrets.token_hex(14)

    session_row = {
        "id": sess_id,
        "api_key_id": chosen.get("id"),
        "status": "active",
        "user_agent": userAgent,
        "viewport_width": viewportWidth,
        "viewport_height": viewportHeight,
        "current_page_id": None,
        "created_at": now,
        "updated_at": now,
        "closed_at": None
    }
    sessions.append(session_row)

    # Update key last_used_at/updated_at (successful authenticated request)
    chosen["last_used_at"] = now
    chosen["updated_at"] = now

    # Log invocation (use tool_invocations as request log; tool_name enum lacks create_session so use echo)
    inv_id = "pwk_call_" + secrets.token_hex(12)
    tool_invocations.append({
        "id": inv_id,
        "api_key_id": chosen.get("id"),
        "session_id": sess_id,
        "page_id": None,
        "tool_name": "echo",
        "status": "succeeded",
        "input": {"tool": "create_session", "userAgent": userAgent, "viewportWidth": viewportWidth, "viewportHeight": viewportHeight},
        "output": {"session": {"id": sess_id}},
        "error_message": None,
        "duration_ms": int((time.time() - t0) * 1000),
        "sequence_no": 0,
        "created_at": now,
        "updated_at": now
    })

    _save("sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("tool_invocations.json", tool_invocations)

    return {"session": session_row}

def close_session(sessionId, **_extra):
    import json, os, datetime, time, secrets, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0338000" if __import__("os").path.isdir("./environment_mix/0338000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        # mimic ULID-ish sortable id without external deps
        return prefix + datetime.datetime.utcnow().strftime("%y%m%d%H%M%S") + "_" + secrets.token_hex(8)

    def _log_invocation(api_key_id, status, session_id=None, page_id=None, err_msg=None, output=None, duration_ms=None):
        tool_invocations = _load("tool_invocations.json")
        inv_id = "pwk_call_" + secrets.token_hex(12)
        row = {
            "id": inv_id,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "page_id": page_id,
            # close_session is not a vendor tool_name; record as echo with raw input, as existing data does
            "tool_name": "echo",
            "status": status,
            "input": {"tool": "close_session", "sessionId": sessionId},
            "output": output,
            "error_message": err_msg,
            "duration_ms": duration_ms,
            "sequence_no": 0,
            "created_at": now,
            "updated_at": now,
        }
        tool_invocations.append(row)
        _save("tool_invocations.json", tool_invocations)
        return inv_id

    def _choose_active_key_for_session(sess, api_keys):
        # If the session references an active key, use it; otherwise, if any active key exists, use it for logging
        if isinstance(sess, dict):
            sid = sess.get("api_key_id")
            if isinstance(sid, str):
                k = next((x for x in api_keys if isinstance(x, dict) and x.get("id") == sid), None)
                if isinstance(k, dict) and k.get("status") == "active":
                    return k
        return next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)

    # Validate input (relax overly strict assumptions: the caller may pass an id that isn't a session id format)
    if not isinstance(sessionId, str) or not sessionId.strip():
        # still log the call
        api_keys = _load("api_keys.json")
        k = next((x for x in api_keys if isinstance(x, dict) and x.get("status") == "active"), None)
        _log_invocation((k.get("id") if k else "unknown"), "failed", None, None, "VALIDATION_ERROR: sessionId must be a non-empty string.",
                        None, int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string.", field="sessionId")

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")

    # Ambient auth: if there exists any active API key, the caller is authenticated.
    active_any = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if not active_any:
        _log_invocation("unknown", "failed", None, None, "UNAUTHORIZED: No active API key available.", None, int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    # Find session. To address observed defect where sessionId might be an API key id, support fallback:
    # - if sessionId matches a session.id: operate on it
    # - else if sessionId matches an api_keys.id: close the most recently updated active/error session for that key
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
    chosen_by = "id"
    if sess is None:
        key_match = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == sessionId), None)
        if isinstance(key_match, dict):
            # pick a closeable session (active or error), prefer most recently updated
            candidates = [s for s in sessions if isinstance(s, dict) and s.get("api_key_id") == key_match.get("id") and s.get("status") in ("active", "error")]
            def _ts(s):
                v = s.get("updated_at") or s.get("created_at") or ""
                return v
            candidates.sort(key=_ts, reverse=True)
            if candidates:
                sess = candidates[0]
                chosen_by = "api_key_fallback"
        # if still none, it's truly not found
    if sess is None:
        _log_invocation(active_any.get("id"), "failed", None, None, "NOT_FOUND: Session not found.", None, int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "Session not found for the authenticated caller.")

    # Authorize based on owning key must be active (business rule)
    owner_key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == sess.get("api_key_id")), None)
    if not owner_key or owner_key.get("status") != "active":
        _log_invocation((owner_key.get("id") if isinstance(owner_key, dict) else active_any.get("id")),
                        "failed", sess.get("id"), sess.get("current_page_id"),
                        "UNAUTHORIZED: API key for this session is not active.", None, int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key for this session is not active; tool calls require an active API key.", rule="api_keys.status must be 'active'")

    # Transition validation
    st = sess.get("status")
    if st == "closed":
        _log_invocation(owner_key.get("id"), "failed", sess.get("id"), sess.get("current_page_id"),
                        "CONFLICT: Session is already closed.", None, int((time.time() - t0) * 1000))
        return _err("CONFLICT", "Session is already closed.")

    if st not in ("active", "error"):
        # illegal transition per lifecycle
        _log_invocation(owner_key.get("id"), "failed", sess.get("id"), sess.get("current_page_id"),
                        f"INVALID_TRANSITION: Cannot close session from status '{st}'.", None, int((time.time() - t0) * 1000))
        return _err("INVALID_TRANSITION", f"Cannot close session from status '{st}'.", from_status=st, to_status="closed")

    # Mutate and persist
    sess["status"] = "closed"
    sess["updated_at"] = now
    sess["closed_at"] = now

    # Write back sessions atomically-ish
    updated = False
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sess.get("id"):
            sessions[i] = sess
            updated = True
            break
    if not updated:
        _log_invocation(owner_key.get("id"), "failed", sess.get("id"), sess.get("current_page_id"),
                        "NOT_FOUND: Session disappeared during update.", None, int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "Session not found.")

    _save("sessions.json", sessions)

    # Update key last_used_at for successful authenticated request
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == owner_key.get("id"):
            k2 = dict(k)
            k2["last_used_at"] = now
            k2["updated_at"] = now
            api_keys[i] = k2
            break
    _save("api_keys.json", api_keys)

    _log_invocation(owner_key.get("id"), "succeeded", sess.get("id"), sess.get("current_page_id"),
                    None, {"session": sess, "resolved_by": chosen_by}, int((time.time() - t0) * 1000))

    return {"session": sess, "resolved_by": chosen_by}

def list_sessions(status=None, pageSize=None, pageToken=None, **_extra):
    import json, os, datetime, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0338000" if __import__("os").path.isdir("./environment_mix/0338000") else "/app/database")
    def _load(n):
