    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validate filters/pagination per tool schema; treat pageToken as opaque string (do not reject arbitrary strings)
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        if status not in ("active", "closed", "error"):
            return _err("VALIDATION_ERROR", "status must be one of: active, closed, error.", field="status", allowed=["active", "closed", "error"])

    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int):
        return _err("VALIDATION_ERROR", "pageSize must be an integer.", field="pageSize")
    if pageSize < 1 or pageSize > 200:
        return _err("VALIDATION_ERROR", "pageSize must be between 1 and 200.", field="pageSize", minimum=1, maximum=200)

    if pageToken is not None and not isinstance(pageToken, str):
        return _err("VALIDATION_ERROR", "pageToken must be a string.", field="pageToken")

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    tool_invocations = _load("tool_invocations.json")

    # Ambient auth: choose an active key that can serve the call.
    key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if not key:
        return _err("UNAUTHORIZED", "API key is missing/invalid or not active.")

    # Rate limit enforcement
    rpm = key.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
        rpm = 60
    cutoff = (now_dt - datetime.timedelta(seconds=60)).isoformat() + "Z"
    recent = 0
    for r in tool_invocations:
        if isinstance(r, dict) and r.get("api_key_id") == key.get("id") and isinstance(r.get("created_at"), str) and r.get("created_at") >= cutoff:
            recent += 1
    if recent >= rpm:
        tool_invocations.append({
            "id": "pwk_call_" + secrets.token_hex(12),
            "api_key_id": key.get("id"),
            "session_id": None,
            "page_id": None,
            "tool_name": "echo",
            "status": "failed",
            "input": {"tool": "list_sessions", "status": status, "pageSize": pageSize, "pageToken": pageToken},
            "output": None,
            "error_message": "Rate limit exceeded.",
            "duration_ms": int((time.time() - t0) * 1000),
            "sequence_no": 0,
            "created_at": now,
            "updated_at": now
        })
        _save("tool_invocations.json", tool_invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_rpm=rpm)

    # Filter sessions by api_key_id and optional status
    filtered = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("api_key_id") != key.get("id"):
            continue
        if status is not None and s.get("status") != status:
            continue
        filtered.append(s)

    # Sort reverse chronological by created_at (string ISO Z works lexicographically)
    filtered.sort(key=lambda r: (r.get("created_at") or ""), reverse=True)

    # Opaque pageToken: if it matches an id in this result set, start AFTER it; else treat as offset cursor if decodable; else start at 0
    start = 0
    if pageToken:
        # Try id-based cursor first
        idx = None
        for i, r in enumerate(filtered):
            if r.get("id") == pageToken:
                idx = i
                break
        if idx is not None:
            start = idx + 1
        else:
            # Try base64url encoded json {"offset": n}
            try:
                pad = "=" * (-len(pageToken) % 4)
                raw = base64.urlsafe_b64decode((pageToken + pad).encode("utf-8"))
                obj = json.loads(raw.decode("utf-8"))
                if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                    start = obj["offset"]
            except Exception:
                start = 0

    page = filtered[start:start + pageSize]
    next_cursor = None
    has_more = (start + pageSize) < len(filtered)
    if has_more and page:
        # Return an opaque cursor; prefer last item's id (works even if caller sends random token)
        next_cursor = page[-1].get("id")

    # Log successful read
    key["last_used_at"] = now
    key["updated_at"] = now
    tool_invocations.append({
        "id": "pwk_call_" + secrets.token_hex(12),
        "api_key_id": key.get("id"),
        "session_id": None,
        "page_id": None,
        "tool_name": "echo",
        "status": "succeeded",
        "input": {"tool": "list_sessions", "status": status, "pageSize": pageSize, "pageToken": pageToken},
        "output": {"count": len(page), "total": len(filtered), "has_more": has_more},
        "error_message": None,
        "duration_ms": int((time.time() - t0) * 1000),
        "sequence_no": 0,
        "created_at": now,
        "updated_at": now
    })
    _save("api_keys.json", api_keys)
    _save("tool_invocations.json", tool_invocations)

    return {
        "sessions": page,
        "page": {
            "total": len(filtered),
            "page_size": pageSize,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }

