    key = None

    if sessionId is not None:
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
        if sess is None:
            # Per contract: reads with filters matching nothing => empty list, not error.
            # But UNAUTHORIZED should only happen if no combination can serve. Here session doesn't exist => empty result set.
            # Still require that some active key exists.
            key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
            if not key:
                return _err("UNAUTHORIZED", "API key is missing/invalid or not active.")
        else:
            key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == sess.get("api_key_id")), None)
            if not key or key.get("status") != "active":
                return _err("UNAUTHORIZED", "API key is missing/invalid or not active.")
    else:
        key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if not key:
            return _err("UNAUTHORIZED", "API key is missing/invalid or not active.")

    # If pageId is provided, ensure it's a real page; if not found => empty result set (no error)
    if pageId is not None:
        page_row = next((p for p in pages if isinstance(p, dict) and p.get("id") == pageId), None)
        if page_row is None:
            # Log and return empty
            rpm = key.get("rate_limit_rpm")
            if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
                rpm = 60
            cutoff = (now_dt - datetime.timedelta(seconds=60)).isoformat() + "Z"
            recent = sum(1 for r in tool_invocations if isinstance(r, dict) and r.get("api_key_id") == key.get("id") and isinstance(r.get("created_at"), str) and r.get("created_at") >= cutoff)
            if recent >= rpm:
                tool_invocations.append({
                    "id": "pwk_call_" + secrets.token_hex(12),
                    "api_key_id": key.get("id"),
                    "session_id": (sess.get("id") if isinstance(sess, dict) else None),
                    "page_id": None,
                    "tool_name": "echo",
                    "status": "failed",
                    "input": {"tool": "list_tool_invocations", "sessionId": sessionId, "pageId": pageId, "toolName": toolName, "status": status, "pageSize": pageSize, "pageToken": pageToken},
                    "output": None,
                    "error_message": "Rate limit exceeded.",
                    "duration_ms": int((time.time() - t0) * 1000),
                    "sequence_no": 0,
                    "created_at": now,
                    "updated_at": now
                })
                _save("tool_invocations.json", tool_invocations)
                return _err("RATE_LIMIT", "Rate limit exceeded.", limit_rpm=rpm)

            key["last_used_at"] = now
            key["updated_at"] = now
            tool_invocations.append({
                "id": "pwk_call_" + secrets.token_hex(12),
                "api_key_id": key.get("id"),
                "session_id": (sess.get("id") if isinstance(sess, dict) else None),
                "page_id": None,
                "tool_name": "echo",
                "status": "succeeded",
                "input": {"tool": "list_tool_invocations", "sessionId": sessionId, "pageId": pageId, "toolName": toolName, "status": status, "pageSize": pageSize, "pageToken": pageToken},
                "output": {"count": 0, "total": 0, "has_more": False},
                "error_message": None,
                "duration_ms": int((time.time() - t0) * 1000),
                "sequence_no": 0,
                "created_at": now,
                "updated_at": now
            })
            _save("api_keys.json", api_keys)
            _save("tool_invocations.json", tool_invocations)
            return {"tool_invocations": [], "page": {"total": 0, "page_size": pageSize, "has_more": False, "next_page_token": None}}

    # Rate limit enforcement
    rpm = key.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
        rpm = 60
    cutoff = (now_dt - datetime.timedelta(seconds=60)).isoformat() + "Z"
    recent = 0
    for r in tool_invocations:
        if isinstance(r, dict) and r.get("api_key_id") == key.get("id") and isinstance(r.get("created_at"), str) and r.get("created_at") >= cutoff:
            recent += 1
    if recent >= rpm:
        tool_invocations.append({
            "id": "pwk_call_" + secrets.token_hex(12),
            "api_key_id": key.get("id"),
            "session_id": (sess.get("id") if isinstance(sess, dict) else None),
            "page_id": None,
            "tool_name": "echo",
            "status": "failed",
            "input": {"tool": "list_tool_invocations", "sessionId": sessionId, "pageId": pageId, "toolName": toolName, "status": status, "pageSize": pageSize, "pageToken": pageToken},
            "output": None,
            "error_message": "Rate limit exceeded.",
            "duration_ms": int((time.time() - t0) * 1000),
            "sequence_no": 0,
            "created_at": now,
            "updated_at": now
        })
        _save("tool_invocations.json", tool_invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_rpm=rpm)

    # Apply filters constrained to authenticated key
    filtered = []
    for inv in tool_invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("api_key_id") != key.get("id"):
            continue
        # tool_invocations schema: non-echo tools imply session_id not null; but listing is just filtering
        if sessionId is not None and inv.get("session_id") != sessionId:
            continue
        if pageId is not None and inv.get("page_id") != pageId:
            continue
        if toolName is not None and inv.get("tool_name") != toolName:
            continue
        if status is not None and inv.get("status") != status:
            continue
        filtered.append(inv)

    # Sorting
    if sessionId is not None:
        # order by (session_id, sequence_no); since single session, sequence_no ascending
        filtered.sort(key=lambda r: (r.get("sequence_no") if isinstance(r.get("sequence_no"), int) else 10**18, r.get("created_at") or ""))
    else:
        # creation time descending
        filtered.sort(key=lambda r: (r.get("created_at") or ""), reverse=True)

    # Pagination: treat token as opaque.
    start = 0
    if pageToken:
        # try id cursor: start after the row with id==pageToken in this filtered order
        idx = None
        for i, r in enumerate(filtered):
            if r.get("id") == pageToken:
                idx = i
                break
        if idx is not None:
            start = idx + 1
        else:
            # try base64url json {"offset": n}
            try:
                pad = "=" * (-len(pageToken) % 4)
                raw = base64.urlsafe_b64decode((pageToken + pad).encode("utf-8"))
                obj = json.loads(raw.decode("utf-8"))
                if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                    start = obj["offset"]
            except Exception:
                start = 0

    page = filtered[start:start + pageSize]
    has_more = (start + pageSize) < len(filtered)
    next_cursor = (page[-1].get("id") if has_more and page else None)

    # Log success (read)
    key["last_used_at"] = now
    key["updated_at"] = now
    tool_invocations.append({
        "id": "pwk_call_" + secrets.token_hex(12),
        "api_key_id": key.get("id"),
        "session_id": (sessionId if sessionId is not None else None),
        "page_id": (pageId if pageId is not None else None),
        "tool_name": "echo",
        "status": "succeeded",
        "input": {"tool": "list_tool_invocations", "sessionId": sessionId, "pageId": pageId, "toolName": toolName, "status": status, "pageSize": pageSize, "pageToken": pageToken},
        "output": {"count": len(page), "total": len(filtered), "has_more": has_more},
        "error_message": None,
        "duration_ms": int((time.time() - t0) * 1000),
        "sequence_no": 0,
        "created_at": now,
        "updated_at": now
    })

    _save("api_keys.json", api_keys)
    _save("tool_invocations.json", tool_invocations)

    return {
        "tool_invocations": page,
        "page": {
            "total": len(filtered),
            "page_size": pageSize,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }
